using MaintenancePRO.Services; namespace MaintenancePRO.ViewModels; public sealed class DashboardViewModel:BaseViewModel { public DemoDataService Data {get;} public int EquipmentCount=>Data.Equipments.Count; public int OpenCount=>Data.Records.Count(x=>x.Status=="Ouverte"||x.Status=="En cours"); public DashboardViewModel(DemoDataService data){Data=data;} public Command OpenEquipment=>new(async()=>await Shell.Current.GoToAsync("//equipments/equipment-list")); public Command NewBreakdown=>new(async()=>await Shell.Current.GoToAsync("//breakdown/breakdown-form")); public Command OpenHistory=>new(async()=>await Shell.Current.GoToAsync("//history/machine-history")); }